const byId = id => document.getElementById(id);
const profileIndexKey='pokemon-arena-player-index';
const defaultPlayer={id:'default',name:'Player 1'};
let playerIndex={active:defaultPlayer.id,players:[defaultPlayer]};
try {
 const saved=JSON.parse(localStorage.getItem(profileIndexKey));
 if(Array.isArray(saved?.players) && saved.players.every(player=>typeof player?.name==='string' &&
   typeof player.id==='string' && /^[a-z0-9-]+$/.test(player.id)) &&
   saved.players.some(player=>player.id===saved.active) &&
   new Set(saved.players.map(player=>player.id)).size===saved.players.length) playerIndex=saved;
} catch {}
const currentPlayer=playerIndex.players.find(player=>player.id===playerIndex.active);
const onlineSaveId=sessionStorage.getItem('arena-online-user');
function playerSaveKey(key) {
 if(onlineSaveId) return 'arena-online:'+onlineSaveId+':'+key;
 return currentPlayer.id==='default'?key:'pokemon-arena-player:'+currentPlayer.id+':'+key;
}
const playerStorage={
 getItem:key=>localStorage.getItem(playerSaveKey(key)),
 setItem:(key,value)=>{localStorage.setItem(playerSaveKey(key),value);window.queueArenaSave?.();}
};
const profileSelect=byId('profile-select');
const profileName=byId('profile-name');
const profileMessage=byId('profile-message');
for(const player of playerIndex.players) {
 const option=document.createElement('option');
 option.value=player.id;
 try {
  const key=player.id==='default'?'pokemon-arena-starter':'pokemon-arena-player:'+player.id+':pokemon-arena-starter';
  option.textContent=JSON.parse(localStorage.getItem(key))?.ign || player.name;
 } catch {option.textContent=player.name;}
 profileSelect.append(option);
}
profileSelect.value=currentPlayer.id;
function switchPlayer(nextIndex,enter=false) {
 try {localStorage.setItem(profileIndexKey,JSON.stringify(nextIndex));}
 catch {
  profileSelect.value=currentPlayer.id;
  profileMessage.textContent='This browser could not save the profile.';
  return;
 }
 if(enter) {try {sessionStorage.setItem('pokemon-arena-enter-profile',nextIndex.active);} catch {}}
 window.location.reload();
}
byId('login-enter').onclick=()=>{
 if(profileSelect.value===currentPlayer.id) openMenu();
 else if(playerIndex.players.some(player=>player.id===profileSelect.value))
  switchPlayer({...playerIndex,active:profileSelect.value},true);
};
byId('player-profiles').onsubmit=event=>{
 event.preventDefault();
 const name=profileName.value.trim().slice(0,24);
 if(!name) {profileMessage.textContent='Enter a player name.';return;}
 if(playerIndex.players.some(player=>player.name.toLowerCase()===name.toLowerCase())) {
  profileMessage.textContent='That player name is already in use.';
  return;
 }
 const id=Array.from(crypto.getRandomValues(new Uint8Array(16)),byte=>byte.toString(16).padStart(2,'0')).join('');
 switchPlayer({active:id,players:[...playerIndex.players,{id,name}]},true);
};

// A future server can supply a transport with send(message) and subscribe(handler).
// This interface carries session messages only. Local saves and battle rules stay separate.
const onlineProtocolVersion=1;
window.PokemonArenaOnline=Object.freeze({
 version:onlineProtocolVersion,
 connect(transport,onMessage) {
  if(typeof transport?.send!=='function' || typeof transport.subscribe!=='function' || typeof onMessage!=='function')
   throw new TypeError('Online sessions require a transport and a message handler.');
  let closed=false;
  const unsubscribe=transport.subscribe(message=>{
   if(!closed && message?.version===onlineProtocolVersion && typeof message.type==='string')
    onMessage(message);
  });
  return Object.freeze({
   send(type,payload=null) {
    if(closed) throw new Error('Online session is closed.');
    if(typeof type!=='string' || !type.trim()) throw new TypeError('A message type is required.');
    return transport.send({version:onlineProtocolVersion,type,payload});
   },
   close() {
    if(closed) return;
    closed=true;
    if(typeof unsubscribe==='function') unsubscribe();
   }
  });
 }
});
