// The Showdown icon sheet provides an offline sprite for every base species.
const iconSheet = new Image();
iconSheet.src = './assets/pokemon-icons.png';
const remoteSprites = new Map();
function getSprite(name) {
 if(!remoteSprites.has(name)) {
  const id = dex[name][0];
  const [left,top,width,height] = iconBounds[id-1];
  const sprite = {image:iconSheet,width,height,
   sx:id%12*40+left,sy:Math.floor(id/12)*30+top};
  remoteSprites.set(name,sprite);
 }
 return remoteSprites.get(name);
}
