const pmdImages=pmdData.pages.map(()=>null);
const pmdClipCache=new Map();
function pmdImage(index) {
 if(!pmdImages[index]) {
  const image=new Image();
  pmdImages[index]=image;
  image.src=pmdData.pages[index];
 }
 return pmdImages[index];
}
const pmdMotionOptions={
 idle:['Idle'],walk:['Walk'],run:['Run','Walk'],
 attack:['Shoot','Attack'],lunge:['Strike','Attack','Charge'],hit:['Hurt','Pain']
};
function pmdClips(name) {
 const id=dex[name][0];
 if(!pmdClipCache.has(id)) {
  const clips={};
  for(const [key,directions] of Object.entries(pmdData.motions[id] ?? {})) {
   clips[pmdData.names[key]]=directions.map(frames=>{
    if(!frames) return null;
    let duration=0;
    return {frames:frames.map(([rect,x,y,ticks])=>{
     duration+=ticks;
     const [page,sx,sy,width,height]=pmdData.rects[rect];
     return {page,sx,sy,width,height,x,y,end:duration};
    }),duration};
   });
  }
  pmdClipCache.set(id,clips);
 }
 return pmdClipCache.get(id);
}
function pmdDirection(dx,dy) {
 return (Math.round(Math.atan2(dx,dy)/(Math.PI/4))+8)%8;
}
function pmdReference(name) {
 const clips=pmdClips(name);
 const rows=clips.Idle ?? clips.Walk ?? Object.values(clips)[0];
 return (rows?.[6] ?? rows?.find(Boolean))?.frames[0];
}
function battleArt(name) {
 return pmdReference(name) ?? getSprite(name);
}
function pmdMotion(actor,motion) {
 const clips=pmdClips(actor.name);
 for(const name of pmdMotionOptions[motion]) {
  const rows=clips[name];
  const row=rows?.[actor.direction] ?? rows?.find(Boolean);
  if(row) return {name,...row};
 }
 return null;
}
function pmdBattleFrame(actor,motion) {
 const clip=pmdMotion(actor,motion);
 if(!clip) return null;
 const {frames,duration}=clip;
 const loop=['idle','walk','run'].includes(motion);
 const moving=motion==='walk'||motion==='run';
 const elapsed=motion==='hit' ? actor.hitSpan-actor.hit : actor.attackSpan-actor.attack;
 const time=loop ? (moving ? actor.motionTicks : visualTime*60+dex[actor.name][0])%duration :
  Math.max(0,Math.min(duration-0.001,elapsed*60));
 return frames.find(frame=>time<frame.end) ?? frames[0];
}
function isFlying(actor) {
 return actor.type==='Flying' || extraTypes[actor.name]==='Flying';
}
function effectiveness(element,target) {
 const row = typeChart[element] ?? {};
 return (row[target.type] ?? 1)*(row[extraTypes[target.name]] ?? 1);
}
