  if(!touchStart) return;
  const {clientX:x,clientY:y}=event.touches[0];
  if(!preview) {
   if(Math.hypot(x-touchStart.x,y-touchStart.y)>10) clearTouch();
   return;
  }
  event.preventDefault();
  preview.style.left=x+'px';
  preview.style.top=y+'px';
  highlightDrop(document.elementFromPoint(x,y)?.closest('[data-roster-slot]') ?? null);
