function hiddenAbilityFor(name,profile) {
 return (profile.pid>>>16)%5===0 ? speciesAbilities[dex[name][0]]?.[1] ?? null : null;
}
function abilityFor(name,profile) {
 const hidden=hiddenAbilityFor(name,profile);
 const regular=speciesAbilities[dex[name][0]]?.[0] ?? [];
 return hidden ?? regular[(profile.pid>>>8)%regular.length] ?? null;
}
