function renderSkillSlots(name) {
 const grid=element('div',null,'move-grid');
 const moves=movesFor(name);
 const available=visibleArenaMoves().filter(move=>wildProgress.skills[move]>0 && !moves.includes(move));
 moves.forEach((move,slot)=>{
  const card=element('div',null,'skill-teach');
  card.append(element('strong',(slot+1)+'. '+move),element('small',moveCatalog[move][0]+' · '+moveRules(move).cooldown.toFixed(1)+'s cooldown'));
  if(available.length) {
   const select=element('select');
   select.setAttribute('aria-label','Skill item for move slot '+(slot+1));
   const blank=element('option','Select skill item');
   blank.value='';
   select.append(blank);
   for(const optionMove of available) {
    const item=skillItem(optionMove);
    const option=element('option',item.name+' ×'+wildProgress.skills[optionMove]);
    option.value=optionMove;
    select.append(option);
   }
   const teach=element('button','Teach');
   teach.disabled=true;
   select.onchange=()=>{teach.disabled=!select.value;};
   teach.onclick=()=>{
    if(!teachSkill(name,slot,select.value)) return;
    const learned=select.value;
    renderDetail();
    byId('pokemon-detail').append(element('p',name+' learned '+learned+'.','skill-lesson-status'));
   };
   card.append(select,teach);
  }
  grid.append(card);
 });
 if(!available.length) grid.append(element('small','Buy skill items in the Skill Shop to replace moves.'));
 return grid;
}
const levelEvolutions={};
for(const [id,[parent,,level]] of Object.entries(evolutionData)) {
 const name=speciesById[id];
 if(parent && level && isAvailablePokemon(name)) (levelEvolutions[parent] ??=[]).push({name,level});
}
function experienceNeeded(level) {
 return (level+1)**3-level**3;
}
function gainWildExperience(name,xp) {
 const entry=ownedPokemon(name);
 entry.xp+=xp;
 const oldLevel=entry.level;
 while(entry.level<100 && entry.xp>=experienceNeeded(entry.level)) {
  entry.xp-=experienceNeeded(entry.level);
  entry.level++;
 }
 if(entry.level===100) entry.xp=0;
 const messages=[];
 if(entry.level>oldLevel) messages.push(name+' reached Lv. '+entry.level+'.');
 if(entry.level>oldLevel) {
  const rule=(levelEvolutions[dex[name][0]] ?? []).find(rule=>entry.level>=rule.level && !ownedPokemon(rule.name));
  if(rule) {
   const evolved=rule.name;
   const sourceId=dex[name][0],targetId=dex[evolved][0];
   profiles[targetId]=profileFor(name);
   try {playerStorage.setItem(profileStorage,JSON.stringify(profiles));} catch {}
   loadouts[evolved]=[...movesFor(name)];
   wildProgress.owned[evolved]=entry;
   if(wildProgress.held[name]) {
    wildProgress.held[evolved]=wildProgress.held[name];
    delete wildProgress.held[name];
   }
   registerPokemon(name);
   registerPokemon(evolved);
   delete wildProgress.owned[name];
   const slot=team.indexOf(name);
   if(slot>=0) team[slot]=evolved;
   saveTeam();
   messages.push(name+' evolved into '+evolved+'!');
  }
 }
 saveWildProgress();
 return messages;
}
