function catchChance(ball,encounter) {
 const legendary=isLegendaryEncounter(encounter.name);
 const multiplier=ball.multiplier(encounter);
 if(multiplier===Infinity) return legendary ? 0.95 : 1;
 const raw=evolutionData[dex[encounter.name][0]][1]/255*multiplier;
 return legendary ? Math.min(0.10,raw*0.5) : Math.max(0.11,Math.min(1,raw));
}

