const habitatNames=['','caves','forests','grasslands','mountains','rare habitats','rough terrain','the sea','cities','waterways'];
let catalogPage=0;
let catalogSelected=null;
const catalogGeneration=byId('dex-generation');
for(let index=0;index<=wildRegions.length;index++) {
 const option=element('option',index ? wildRegions[index-1] : 'All regions');
 option.value=String(index);
 catalogGeneration.append(option);
}
function dexLock() {
 const badge=element('span',null,'dex-lock-badge');
 badge.setAttribute('aria-hidden','true');
 badge.append(element('span',null,'dex-lock'));
 return badge;
}
function describeSpecies(name) {
 const [id,primary,secondary]=dex[name];
 const [category,habitat]=dexDescriptions[id];
 const [height,weight]=dimensions(name);
 const region=wildRegions[generationOf(name)-1];
 const [parent]=evolutionData[id];
 const family=parent ? ' It evolves from '+speciesById[parent]+'.' : '';
 const home=habitatNames[habitat] ? ' Its listed habitat is '+habitatNames[habitat]+'.' : '';
 return name+' is the '+category+', a '+(secondary?primary+'/'+secondary:primary)+
  '-type species first introduced in '+region+'. It measures '+height/10+' m and weighs '+weight/10+' kg.'+home+family;
}
function renderCatalogDetail(name) {
 const panel=byId('dex-detail');
 panel.replaceChildren();
 if(!name) {panel.append(element('p','No matching Pokémon.'));return;}
 const caught=registeredPokemon.has(name);
 const [,primary,secondary]=dex[name];
 const title=element('h3',caught ? dexNumber(name)+' '+name : dexNumber(name));
 const art=element('div',null,'dex-art'+(caught?'':' is-uncaught'));
 art.append(pokemonPortrait(name));
 if(!caught) {
  art.append(dexLock());
  panel.append(title,art);
  return;
 }
 const status=element('p',(secondary?primary+' / '+secondary:primary)+' · '+'Registered','dex-status');
 const stats=element('dl',null,'dex-base-stats');
 dexStats[dex[name][0]-1].forEach((value,index)=>{
  const cell=element('div');
  cell.append(element('dt',statLabels[index]),element('dd',String(value)));
  stats.append(cell);
 });
 panel.append(title,art,status);
 panel.append(element('p',describeSpecies(name),'dex-description'));
 panel.append(element('h4','Base stats'),stats);
}
function renderCatalog() {
 const query=byId('dex-search').value.trim().toLowerCase();
 const numeric=query.replace(/^#/,'');
 const generation=Number(catalogGeneration.value);
 const registration=byId('dex-registration').value;
 const names=dexNames.filter(name=>(!generation || generationOf(name)===generation) &&
  (registration!=='registered' || registeredPokemon.has(name)) &&
  (registration!=='unregistered' || !registeredPokemon.has(name)) &&
  (!query || (registeredPokemon.has(name) && name.toLowerCase().includes(query)) ||
   (/^\d+$/.test(numeric) && (dex[name][0]===Number(numeric) || dexNumber(name).slice(1).startsWith(numeric)))));
 const pages=Math.max(1,Math.ceil(names.length/boxSize));
 catalogPage=clamp(catalogPage,0,pages-1);
 const page=names.slice(catalogPage*boxSize,(catalogPage+1)*boxSize);
 if(!page.includes(catalogSelected)) catalogSelected=page[0] ?? null;
 byId('dex-progress').textContent=registeredPokemon.size+' / '+dexNames.length+' registered';
 byId('dex-page').textContent='Page '+(catalogPage+1)+' / '+pages+' · '+names.length+' entries';
 byId('dex-prev').disabled=catalogPage===0;
 byId('dex-next').disabled=catalogPage===pages-1;
 const grid=byId('dex-grid');
 grid.replaceChildren(...page.map((name,index)=>{
  const caught=registeredPokemon.has(name);
  const tile=pokemonTile(name,caught?'Registered':'Uncaught',name===catalogSelected,()=>{
   catalogSelected=name;
   renderCatalog();
   grid.children[index].focus();
  });
  tile.className+=' dex-tile'+(caught?'':' is-uncaught');
  if(!caught) {
   tile.title=dexNumber(name);
   tile.setAttribute('aria-label','Uncaught '+dexNumber(name));
   tile.append(dexLock());
  }
  return tile;
 }));
 renderCatalogDetail(catalogSelected);
}
function openPokedex() {
 phase='pokedex';
 showScreen('pokedex');
 renderCatalog();
}
byId('dex-search').oninput=()=>{catalogPage=0;renderCatalog();};
